#!/usr/bin/env python3
"""Read ids.txt and print the next order id."""

import sys


def base36_encode(n):
    """Encode an integer as a base-36 string using 0-9, A-Z."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if n == 0:
        return "0"
    result = []
    while n > 0:
        result.append(chars[n % 36])
        n //= 36
    return "".join(reversed(result))


def base36_decode(s):
    """Decode a base-36 string to an integer."""
    return int(s, 36)


def main():
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("ORD-0000")
        return

    if not lines:
        print("ORD-0000")
        return

    last_id = lines[-1]
    prefix = last_id[:4]  # "ORD-"
    suffix = last_id[4:]  # e.g., "243G"

    next_num = base36_decode(suffix) + 1
    next_suffix = base36_encode(next_num).zfill(4).upper()
    print(f"{prefix}{next_suffix}")


if __name__ == "__main__":
    main()

