import sys

def base36_encode(n):
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if n == 0:
        return '0'
    result = ''
    while n > 0:
        result = chars[n % 36] + result
        n //= 36
    return result

def base36_decode(s):
    return int(s, 36)

def next_id(last_id):
    suffix = last_id.split('-')[1]
    num = base36_decode(suffix)
    next_num = num + 1
    next_suffix = base36_encode(next_num).zfill(4)
    return f'ORD-{next_suffix}'

def main():
    with open('ids.txt') as f:
        lines = [line.strip() for line in f if line.strip()]
    last_id = lines[-1]
    print(next_id(last_id))

if __name__ == '__main__':
    main()

