import sys

def inc_base36(s: str) -> str:
    """Increment a base-36 string by 1, preserving zero-padded width."""
    chars = list(s)
    for i in range(len(chars) - 1, -1, -1):
        c = chars[i]
        if '0' <= c <= '8':
            chars[i] = chr(ord(c) + 1)
            return ''.join(chars)
        if c == '9':
            chars[i] = 'A'
            return ''.join(chars)
        if 'A' <= c <= 'Y':
            chars[i] = chr(ord(c) + 1)
            return ''.join(chars)
        if c == 'Z':
