"""gen_id.py — print the next order id to stdout.

Ids have the form ORD- followed by four characters drawn from a
confusion-free alphabet (no 0/O, 1/I, L, Q — see MemPalace analysis of
ORD-23I0 / ORD-2310 incident).

Usage:
    python gen_id.py
"""

import sys

# Confusion-free alphabet recommended by incident analysis.
# Excludes 0,1,I,O,L,Q — all known to cause voice/print mix-ups.
ALPHABET = "23456789ABCDEFGHJKLMNPQRSTUVWXYZ"
BASE = len(ALPHABET)  # 30
CHAR_TO_VAL = {c: i for i, c in enumerate(ALPHABET)}
ID_LEN = 4
PREFIX = "ORD-"


def _encode(val: int) -> str:
    """Convert an integer to a 4-character id suffix."""
    chars = []
    for _ in range(ID_LEN):
        chars.append(ALPHABET[val % BASE])
        val //= BASE
    return "".join(reversed(chars))


def _decode(suffix: str) -> int:
    """Convert a 4-character id suffix to an integer."""
    val = 0
    for c in suffix:
        val = val * BASE + CHAR_TO_VAL[c]
    return val


def next_id(current: str) -> str:
    """Return the next order id after the given one."""
    if not current.startswith(PREFIX):
        raise ValueError(f"Id must start with {PREFIX!r}: {current!r}")

    suffix = current[len(PREFIX):]
    if len(suffix) != ID_LEN:
        raise ValueError(f"Id suffix must be {ID_LEN} characters: {current!r}")

    for c in suffix:
        if c not in CHAR_TO_VAL:
            raise ValueError(
                f"Character {c!r} is not in the confusion-free alphabet: {current!r}"
            )

    val = _decode(suffix)
    val += 1

    if val >= BASE ** ID_LEN:
        raise ValueError("ID space exhausted")

    return PREFIX + _encode(val)


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        print("Error: ids.txt not found", file=sys.stderr)
        sys.exit(1)

    if not lines:
        # Start from the first id: the lowest 4-char value in the alphabet
        print(PREFIX + _encode(0))
        return

    last = lines[-1]
    try:
        nxt = next_id(last)
    except ValueError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

    print(nxt)


if __name__ == "__main__":
    main()

