import os
import glob

def main():
    inbox_dir = "inbox"
    measurements = []

    # Read every .txt file in inbox/
    for txt_file in sorted(glob.glob(os.path.join(inbox_dir, "*.txt"))):
        with open(txt_file, "r") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                # Split optionally by whitespace/tab and try to get integer
                parts = line.split()
                if len(parts) >= 2:
                    try:
                        measurements.append(int(parts[1]))
                    except ValueError:
                        pass
                elif len(parts) == 1:
                    try:
                        measurements.append(int(parts[0]))
                    except ValueError:
                        pass

    n = len(measurements)
    total = sum(measurements)

    if n > 0:
        average = total / n
    else:
        average = 0.0

    with open("report.txt", "w") as f:
        f.write(f"entries {n}\n")
        f.write(f"total {total}\n")
        f.write(f"average {average:.2f}\n")

if __name__ == "__main__":
    main()

