#!/usr/bin/env python3
import sys
from pathlib import Path

VERSION_FILE = Path(__file__).parent / "VERSION"
RELEASES_FILE = Path(__file__).parent / "releases.log"


def main() -> None:
    version = VERSION_FILE.read_text().strip()
    if not version:
        print("error: VERSION file is empty", file=sys.stderr)
        sys.exit(1)

    releases = RELEASES_FILE.read_text().strip().splitlines()

    # Idempotent: don't add the version if it already exists
    if version not in releases:
        with open(RELEASES_FILE, "a") as f:
            f.write(version + "\n")
        print(f"Registered version {version}")
    else:
        print(f"Version {version} already registered (skipping)")


if __name__ == "__main__":
    main()

