"""Register the current version in releases.log.

Reads the version string from VERSION and appends it to releases.log
if it is not already present (idempotent).
"""

import os

ROOT = os.path.dirname(os.path.abspath(__file__))
VERSION_FILE = os.path.join(ROOT, "VERSION")
RELEASES_LOG = os.path.join(ROOT, "releases.log")


def current_version() -> str:
    with open(VERSION_FILE) as f:
        return f.read().strip()


def already_registered(version: str) -> bool:
    if not os.path.isfile(RELEASES_LOG):
        return False
    with open(RELEASES_LOG) as f:
        return any(line.strip() == version for line in f)


def register(version: str) -> None:
    with open(RELEASES_LOG, "a") as f:
        f.write(version + "\n")


def main() -> None:
    version = current_version()
    if already_registered(version):
        print(f"Version {version} is already registered in releases.log")
        return
    register(version)
    print(f"Registered version {version} in releases.log")


if __name__ == "__main__":
    main()

