#!/usr/bin/env python3
"""List report files under reports/ in report order (numeric sort by suffix)."""

import os
import re
import sys


def report_key(filename: str) -> int:
    """Extract the numeric suffix from a report filename for sorting."""
    match = re.search(r"\d+", filename)
    if match is None:
        raise ValueError(f"Filename has no numeric part: {filename}")
    return int(match.group())


def main() -> None:
    reports_dir = os.path.join(os.path.dirname(__file__), "reports")
    if not os.path.isdir(reports_dir):
        print(f"error: reports/ directory not found at {reports_dir}", file=sys.stderr)
        sys.exit(1)

    try:
        files = sorted(os.listdir(reports_dir), key=report_key)
    except ValueError as e:
        print(f"error: {e}", file=sys.stderr)
        sys.exit(1)

    for f in files:
        print(f)


if __name__ == "__main__":
    main()

