#!/usr/bin/env python3
"""Generate manifest.json with SHA-256 digests for every file under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path("release")
MANIFEST_PATH = Path("manifest.json")


def sha256_digest(path: Path) -> str:
    """Return the hex SHA-256 digest of a file."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest = {}
    # Walk release/ sorted for deterministic output.
    for path in sorted(RELEASE_DIR.rglob("*")):
        if path.is_file():
            rel = str(path.relative_to(RELEASE_DIR.parent))
            manifest[rel] = sha256_digest(path)

    MANIFEST_PATH.write_text(
        json.dumps(manifest, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    print(f"Wrote {len(manifest)} entries to {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

