import os
import glob
from collections import Counter

PUNCTUATION = set(".,;:!?")

def strip_edge_punctuation(word):
    """Strip punctuation characters from edges of a word."""
    while word and word[0] in PUNCTUATION:
        word = word[1:]
    while word and word[-1] in PUNCTUATION:
        word = word[:-1]
    return word

def main():
    counter = Counter()
    docs_dir = "docs"
    # Find all .txt files under docs/ recursively
    txt_files = glob.glob(os.path.join(docs_dir, "**", "*.txt"), recursive=True)

    for filepath in txt_files:
        with open(filepath, "r", encoding="utf-8") as f:
            for line in f:
                raw_words = line.strip().split()
                for raw in raw_words:
                    word = strip_edge_punctuation(raw).lower()
                    if word:  # skip empty strings
                        counter[word] += 1

    # Write counts.txt sorted alphabetically
    with open("counts.txt", "w", encoding="utf-8") as out:
        for word in sorted(counter):
            out.write(f"{word} {counter[word]}\n")

if __name__ == "__main__":
    main()

