cat > rotate.py << 'EOF'
#!/usr/bin/env python3
"""Rotate app.log entries older than 7 days before AS_OF into archive.log.

Usage: python rotate.py AS_OF   (AS_OF = Unix timestamp in integer seconds)

app.log timestamps are UTC (no suffix). Both app.log and archive.log are
one entry per line, newest last, ordered chronologically.
"""

import sys
from datetime import datetime, timedelta, timezone

LOG_TS_FMT = "%Y-%m-%d %H:%M:%S"
CUTOFF_DAYS = 7


def parse_log_ts(line: str) -> datetime:
    """Parse the leading YYYY-MM-DD HH:MM:SS timestamp as UTC (naive -> UTC)."""
    ts = line[:19]
    try:
        naive = datetime.strptime(ts, LOG_TS_FMT)
    except ValueError:
        raise ValueError(f"line does not start with YYYY-MM-DD HH:MM:SS: {line!r}")
    return naive.replace(tzinfo=timezone.utc)


def main() -> None:
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python rotate.py AS_OF  (AS_OF = Unix timestamp in integer seconds)")

    try:
        as_of = datetime.fromtimestamp(int(sys.argv[1]), tz=timezone.utc)
    except (ValueError, OverflowError, OSError):
        raise SystemExit(f"invalid AS_OF Unix timestamp: {sys.argv[1]!r}")
    cutoff = as_of - timedelta(days=CUTOFF_DAYS)

    with open("app.log", "r", newline="") as fh:
        lines = fh.read().splitlines(keepends=True)

    stale, keep = [], []
    for line in lines:
        if not line.strip():
            continue
        if parse_log_ts(line) < cutoff:
            stale.append(line)
        else:
            keep.append(line)

    if stale:
        with open("archive.log", "a", newline="") as fh:
            fh.write("".join(stale))

    with open("app.log", "w", newline="") as fh:
        fh.write("".join(keep))


if __name__ == "__main__":
    main()
EOF
echo "wrote rotate.py" && python3 -m py_compile rotate.py && echo "compiles OK" && cat -A rotate.py | sed -n '1,10p'

