import sys
import time
from datetime import datetime, timedelta

def parse_timestamp(line):
    """Parse 'YYYY-MM-DD HH:MM:SS' at start of a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
    except ValueError:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff_dt = datetime.fromtimestamp(as_of) - timedelta(days=7)

    with open("app.log", "r") as f:
        lines = f.readlines()

    kept = []
    archived = []

    for line in lines:
        dt = parse_timestamp(line)
        if dt is not None and dt < cutoff_dt:
            archived.append(line)
        else:
            kept.append(line)

    if archived:
        with open("archive.log", "a") as f:
            f.writelines(archived)

    with open("app.log", "w") as f:
        f.writelines(kept)

if __name__ == "__main__":
    main()

